            ScaleMode::MinorPentatonic,
            ScaleMode::Hirajoshi,
            ScaleMode::InSen,
            ScaleMode::Iwato,
            ScaleMode::Yo,
            ScaleMode::Kumoi,
            ScaleMode::Pelog,
            // Blues & Bebop (3)
            ScaleMode::MinorBlues,
            ScaleMode::MajorBlues,
            ScaleMode::BebopDominant,
            // Symmetric (4)
            ScaleMode::WholeTone,
            ScaleMode::DiminishedWholeHalf,
            ScaleMode::DiminishedHalfWhole,
            ScaleMode::AugmentedHex,
            // World (5)
            ScaleMode::Enigmatic,
            ScaleMode::NeapolitanMinor,
