    fn octave_shift_to_side(harmony: Note, anchor: Note, above: bool) -> Option<Note> {
        let anchor_midi = u8::from(anchor) as i16;
        let mut harm_midi = u8::from(harmony) as i16;
        let on_correct_side = if above {
            harm_midi > anchor_midi
        } else {
            harm_midi < anchor_midi
        };
        if on_correct_side {
            return Some(harmony);
